import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))
    target = int(data[1+n])

    if n == 0:
        print("-1")
        return

    num_to_index = {}
    for i in range(n):
        complement = target - arr[i]
        if complement in num_to_index:
            print(f"{num_to_index[complement]} {i}")
            return
        num_to_index[arr[i]] = i

    print("-1")

if __name__ == "__main__":
    main()
